// Auto-generated from Anytap policy documents (tables preserved).
export const LEGAL = {"privacy":{"title":"Privacy Policy","effective":"Effective Date: June 1, 2026   |   Last Updated: June 1, 2026","blocks":[{"t":"h2","x":"1. Introduction"},{"t":"p","x":"Anytap (\"we,\" \"us,\" or \"our\") is committed to protecting your personal information. This Privacy Policy explains how we collect, use, store, share, and protect information about you when you access or use the Anytap Card, Anytap Pay, and any related mobile or web application (collectively, the \"Services\")."},{"t":"p","x":"By using the Services, you acknowledge that you have read and understood this Privacy Policy. If you do not agree with this Policy, you must discontinue use of the Services."},{"t":"h2","x":"2. Information We Collect"},{"t":"p","x":"We collect information in the following categories:"},{"t":"h3","x":"2.1 Identity and Verification Information"},{"t":"p","x":"Full legal name, date of birth, and nationality;"},{"t":"p","x":"Government-issued photo identification (passport, national ID, or driver's license);"},{"t":"p","x":"Selfie or biometric image for identity verification;"},{"t":"p","x":"Proof of residential address (utility bill, bank statement, or equivalent document)."},{"t":"p","x":"KYC data collected through this process is processed by Anytap in accordance with the requirements set out in our card issuance agreement. Anytap is responsible for the collection, handling, and safeguarding of all KYC information submitted by users."},{"t":"h3","x":"2.2 Contact and Account Information"},{"t":"p","x":"Email address and mobile phone number;"},{"t":"p","x":"Account login credentials (stored in encrypted form);"},{"t":"p","x":"Correspondence and communications with our support team."},{"t":"h3","x":"2.3 Financial and Transaction Information"},{"t":"p","x":"Cryptocurrency wallet addresses used for top-up transactions;"},{"t":"p","x":"Card transaction history, including merchant name, amount, currency, and timestamp;"},{"t":"p","x":"ATM withdrawal records;"},{"t":"p","x":"Anytap Pay payment and settlement records (for business users)."},{"t":"h3","x":"2.4 Device and Technical Information"},{"t":"p","x":"IP address and approximate geographic location;"},{"t":"p","x":"Device type, operating system, browser type, and version;"},{"t":"p","x":"App usage data and session logs;"},{"t":"p","x":"Cookies and similar tracking technologies (see Section 9)."},{"t":"h3","x":"2.5 Referral Program Information"},{"t":"p","x":"Referral code usage and referral network activity;"},{"t":"p","x":"Commission and payout records associated with your referral account."},{"t":"h2","x":"3. How We Use Your Information"},{"t":"p","x":"We use the information we collect for the following purposes:"},{"t":"table","rows":[["Purpose","Legal Basis"],["Identity verification (KYC) and fraud prevention","Legal obligation / Legitimate interest"],["Processing card issuance, top-up, and payment transactions","Performance of contract"],["AML / CFT monitoring and compliance reporting","Legal obligation"],["Providing customer support and responding to inquiries","Performance of contract"],["Sending service-related notifications and security alerts","Performance of contract / Legitimate interest"],["Improving the Services and conducting internal analytics","Legitimate interest"],["Administering the referral and partner program","Performance of contract"],["Complying with applicable laws, regulations, and court orders","Legal obligation"],["Sending promotional communications (with your consent)","Consent"]]},{"t":"h2","x":"4. How We Share Your Information"},{"t":"p","x":"We do not sell your personal information to third parties. We may share your information only in the following circumstances:"},{"t":"h3","x":"4.1 Card Issuance Infrastructure Partner"},{"t":"p","x":"To enable card issuance and payment processing, we share necessary identity and financial information with our card infrastructure partner, WasabiCard (Wasabi Group Ltd), which holds the following regulatory licenses: U.S. & Canada MSB, U.S. MTL (Money Transmitter License), PCI DSS Level 1, Singapore Visa TPA, and Singapore Visa PIF. This partner is contractually bound by strict data protection and confidentiality obligations."},{"t":"h3","x":"4.2 Cryptocurrency Wallet Infrastructure Provider"},{"t":"p","x":"We engage a third-party cryptocurrency wallet infrastructure provider to manage the receipt, storage, and processing of cryptocurrency deposits made by users prior to conversion and card top-up. This provider processes data solely on our instructions under a contractual data processing agreement."},{"t":"h3","x":"4.3 KYC / AML Service Providers"},{"t":"p","x":"We engage third-party identity verification and AML screening providers to process KYC submissions and screen transactions. These providers process data solely on our instructions and are contractually prohibited from using your data for any other purpose."},{"t":"h3","x":"4.4 Payment Network Operators"},{"t":"p","x":"Transaction data is shared with the Visa network (for physical cards) and the Visa network, and related payment infrastructure, as required to process and settle card transactions globally."},{"t":"h3","x":"4.5 Legal and Regulatory Authorities"},{"t":"p","x":"We may disclose personal information to law enforcement agencies, financial intelligence units, regulators, or courts where required by applicable law, court order, or regulatory directive, including obligations under AML/CFT laws."},{"t":"h3","x":"4.6 Business Transfers"},{"t":"p","x":"In the event of a merger, acquisition, asset sale, or corporate restructuring, your information may be transferred as part of that transaction. We will notify you of any such change via email or prominent notice on our website prior to your data being transferred and becoming subject to a different privacy policy."},{"t":"h3","x":"4.7 With Your Consent"},{"t":"p","x":"We may share your information with other third parties where you have given us your explicit consent to do so."},{"t":"h2","x":"5. Data Retention"},{"t":"p","x":"We retain personal information for as long as necessary to fulfill the purposes for which it was collected, or as required by applicable law. The following retention periods apply as a general guideline:"},{"t":"table","rows":[["Category","Retention Period"],["KYC / Identity verification records","Minimum 5 years after account closure (as required by AML regulations)"],["Transaction records","Minimum 5 years after transaction date"],["Account and contact information","Duration of account, plus 5 years after closure"],["Support and correspondence records","3 years from date of communication"],["Marketing consent records","Until consent is withdrawn, plus 3 years"]]},{"t":"p","x":"Where retention is required solely for legal or regulatory compliance, data is stored securely and access is restricted to authorized personnel only."},{"t":"h2","x":"6. Data Security"},{"t":"p","x":"We implement industry-standard technical and organizational security measures to protect your personal information against unauthorized access, alteration, disclosure, or destruction. These measures include:"},{"t":"p","x":"Encryption of data in transit using TLS (Transport Layer Security);"},{"t":"p","x":"Encryption of sensitive data at rest;"},{"t":"p","x":"Two-factor authentication (2FA) for account access;"},{"t":"p","x":"Role-based access control (RBAC) to restrict internal data access;"},{"t":"p","x":"Regular security audits and vulnerability assessments;"},{"t":"p","x":"PCI DSS Level 1 certified infrastructure for payment data;"},{"t":"p","x":"Card sensitive data (card number, CVV, expiry date) is transmitted using RSA encryption and is never stored in plaintext in our systems."},{"t":"p","x":"While we take all reasonable steps to protect your information, no method of electronic transmission or storage is 100% secure. In the event of a data breach that is likely to result in a risk to your rights and freedoms, we will notify you and relevant authorities in accordance with applicable law."},{"t":"h2","x":"7. International Data Transfers"},{"t":"p","x":"Anytap operates globally and your personal information may be transferred to, stored, and processed in countries other than your country of residence, including the United States and Singapore, where our card infrastructure and wallet service partners operate."},{"t":"p","x":"Where we transfer personal data outside your jurisdiction, we ensure that appropriate safeguards are in place, such as Standard Contractual Clauses (SCCs), adequacy decisions, or equivalent legal mechanisms, to protect your information in accordance with applicable data protection law."},{"t":"h2","x":"8. Your Rights"},{"t":"p","x":"Depending on your country of residence, you may have the following rights with respect to your personal information:"},{"t":"table","rows":[["Right","Description"],["Access","Request a copy of the personal information we hold about you."],["Rectification","Request correction of inaccurate or incomplete personal information."],["Erasure","Request deletion of your personal information, subject to legal retention obligations."],["Restriction","Request that we restrict processing of your data in certain circumstances."],["Data Portability","Receive your personal data in a structured, machine-readable format."],["Objection","Object to processing of your personal data based on legitimate interests."],["Withdraw Consent","Withdraw consent at any time where processing is based on consent."]]},{"t":"p","x":"To exercise any of these rights, please contact us at support@anytap.io. We will respond to verified requests within 30 days. Please note that certain rights may be limited where we are required to retain data under applicable AML, KYC, or financial regulations."},{"t":"h2","x":"9. Cookies and Tracking Technologies"},{"t":"p","x":"Anytap uses cookies and similar tracking technologies on our website and application. We use the following types of cookies:"},{"t":"p","x":"Strictly necessary cookies: Essential for the operation of the Services, including session management and authentication. These cookies cannot be disabled."},{"t":"p","x":"Functional cookies: Allow the Platform to remember your preferences and provide personalized features."},{"t":"p","x":"Analytics cookies: Help us understand how users interact with our Services in order to improve functionality and user experience."},{"t":"p","x":"Security cookies: Used to detect and prevent fraudulent activity, bot traffic, and unauthorized access, including device fingerprinting and session risk scoring."},{"t":"p","x":"We do not use cookies for third-party advertising or behavioral profiling. You may configure your browser to refuse cookies; however, doing so may affect certain features of the Services. For full details, please refer to our Cookie Policy at anytap.io/cookies."},{"t":"h2","x":"10. Children's Privacy"},{"t":"p","x":"The Services are not directed at individuals under the age of 18. We do not knowingly collect personal information from minors. If you believe a minor has submitted personal information to us, please contact us immediately at support@anytap.io and we will take steps to delete such information."},{"t":"h2","x":"11. Third-Party Links"},{"t":"p","x":"Our website or application may contain links to third-party websites or services. This Privacy Policy does not apply to those third-party sites. We are not responsible for the privacy practices or content of any third-party websites and encourage you to review their privacy policies independently."},{"t":"h2","x":"12. Changes to This Privacy Policy"},{"t":"p","x":"We may update this Privacy Policy from time to time to reflect changes in our practices, technology, legal requirements, or other factors. We will provide notice of material changes via email or prominent in-app notification at least 14 days prior to the effective date of any change. The updated Policy will be available at anytap.io/privacy."},{"t":"p","x":"Your continued use of the Services after the effective date of any revised Privacy Policy constitutes your acceptance of the changes."},{"t":"h2","x":"13. Contact Us"},{"t":"p","x":"If you have any questions, concerns, or requests regarding this Privacy Policy or our data practices, please contact us through the appropriate channel below:"},{"t":"table","rows":[["Channel","Contact","Notes"],["General Support","support@anytap.io","English only"],["Business / Partnership","biz@anytap.io","B2B and partnership inquiries"]]},{"t":"p","x":"© 2026 Anytap. All rights reserved."}]},"cookies":{"title":"Cookie Policy","effective":"Effective Date: June 1, 2026   |   Last Updated: June 1, 2026","blocks":[{"t":"h2","x":"1. Introduction"},{"t":"p","x":"Anytap (\"we,\" \"us,\" or \"our\") uses cookies and similar tracking technologies on our website (anytap.io) and mobile application (collectively, the \"Platform\"). This Cookie Policy explains what cookies are, which types we use, why we use them, and how you can manage your cookie preferences."},{"t":"p","x":"This Cookie Policy should be read together with our Privacy Policy (anytap.io/privacy) and Terms of Service (anytap.io/terms), which are incorporated by reference."},{"t":"p","x":"By continuing to use the Anytap Platform after being presented with this Cookie Policy, you consent to our use of cookies as described herein. You may withdraw or adjust your consent at any time through the methods described in Section 6. Withdrawing consent does not affect the lawfulness of any processing based on consent prior to its withdrawal."},{"t":"h2","x":"2. What Are Cookies?"},{"t":"p","x":"Cookies are small text files placed on your device (computer, smartphone, or tablet) when you visit a website or use an application. They are widely used to make platforms work efficiently, to remember user preferences, and to provide operational information to the platform operator."},{"t":"p","x":"In addition to cookies, we may also use similar technologies such as:"},{"t":"p","x":"Web beacons (also known as pixel tags or clear GIFs): Small graphic files embedded in web pages or emails that allow us to track whether a page has been viewed or an email has been opened;"},{"t":"p","x":"Local storage objects (LSOs): Data stored locally in your browser that functions similarly to cookies but with greater storage capacity;"},{"t":"p","x":"Session storage: Temporary data stored for the duration of a single browser session and automatically deleted when the session ends;"},{"t":"p","x":"Device fingerprinting: A technique that collects information about your device configuration to assist in fraud detection, session risk scoring, and the prevention of unauthorized account access."},{"t":"p","x":"For simplicity, all of the above technologies are referred to collectively as \"cookies\" in this Policy."},{"t":"h2","x":"3. Categories of Cookies We Use"},{"t":"p","x":"We classify the cookies used on the Anytap Platform into the following four categories:"},{"t":"h3","x":"3.1 Strictly Necessary Cookies"},{"t":"p","x":"These cookies are essential for the Platform to function and cannot be switched off in our systems. They are typically set in response to actions you take, such as logging in, completing your identity verification (KYC) onboarding, or setting your privacy preferences. The lawful basis for these cookies is contractual necessity and legitimate interest. Without these cookies, core services cannot be provided."},{"t":"table","rows":[["Cookie Name","Purpose","Duration"],["session_id","Maintains your authenticated session while logged in to Anytap","Session"],["csrf_token","Protects against Cross-Site Request Forgery (CSRF) attacks","Session"],["auth_token","Stores encrypted authentication credentials for secure access","30 days"],["kyc_state","Preserves your progress through the identity verification (KYC) onboarding flow required under our card issuance program","Session"],["lang_pref","Remembers your selected language preference","1 year"]]},{"t":"h3","x":"3.2 Functional Cookies"},{"t":"p","x":"These cookies allow the Platform to remember choices you make and provide enhanced, more personalized features. They may be set by us or by third-party providers whose services we have integrated."},{"t":"table","rows":[["Cookie Name","Purpose","Duration"],["ui_theme","Remembers your display preference (light or dark mode)","1 year"],["currency_pref","Stores your preferred display currency for balances","1 year"],["dashboard_layout","Saves your customized dashboard panel arrangement","6 months"],["notification_prefs","Retains your in-app notification settings","1 year"],["referral_code","Tracks referral attribution for commission calculation within the Anytap referral program; commissions are settled at the end of the month following the referral activity","30 days"]]},{"t":"h3","x":"3.3 Analytics Cookies"},{"t":"p","x":"These cookies help us understand how visitors interact with the Platform by collecting and reporting information anonymously. This data helps us improve the structure, content, and performance of our services. We use aggregated, anonymized data only and do not use analytics cookies to identify individual users."},{"t":"table","rows":[["Cookie Name / Provider","Purpose","Duration"],["_ga / Google Analytics","Distinguishes unique users and tracks session data across pages","2 years"],["_gid / Google Analytics","Stores and updates a unique value for each page visited","24 hours"],["_gat / Google Analytics","Used to throttle request rate to Google Analytics servers","1 minute"],["amplitude_id / Amplitude","Tracks user behavior and feature engagement patterns","1 year"],["mixpanel_id / Mixpanel","Monitors product usage events and funnel conversion rates","1 year"]]},{"t":"p","x":"All analytics data is processed in anonymized, aggregated form. We do not share individual-level analytics data with third parties for their own marketing purposes. Analytics providers listed in Section 5 may transfer data internationally. Such transfers are subject to appropriate safeguards including Standard Contractual Clauses (SCCs) or applicable adequacy decisions."},{"t":"h3","x":"3.4 Security Cookies"},{"t":"p","x":"These cookies are used to detect and prevent security threats, including fraudulent login attempts, bot activity, and unauthorized access to accounts."},{"t":"table","rows":[["Cookie Name / Provider","Purpose","Duration"],["__cf_bm / Cloudflare","Identifies and mitigates automated bot traffic","30 minutes"],["recaptcha / Google","Verifies that interactions are performed by a human, not a bot","Session"],["device_fp","Generates a device fingerprint to detect suspicious login patterns and support session risk scoring","90 days"],["fraud_score","Assigns a real-time risk score to sessions for fraud detection and prevention","Session"]]},{"t":"h2","x":"4. Cookies We Do Not Use"},{"t":"p","x":"Anytap is committed to respecting user privacy. We do not use cookies for the following purposes:"},{"t":"p","x":"Behavioral advertising or retargeting: We do not serve personalized advertisements based on your browsing behavior, either on our Platform or on third-party websites;"},{"t":"p","x":"Third-party advertising networks: We do not allow advertising networks to place tracking cookies on the Anytap Platform;"},{"t":"p","x":"Social media tracking pixels: We do not embed social media tracking pixels from platforms such as Facebook, Instagram, or TikTok for the purpose of cross-platform behavioral profiling;"},{"t":"p","x":"Sale of cookie data: We do not sell or transfer cookie-derived data to data brokers or third-party marketers."},{"t":"h2","x":"5. Third-Party Cookies"},{"t":"p","x":"Some cookies on the Anytap Platform are set by third-party service providers we have engaged to deliver certain features. We have executed Data Processing Agreements (DPAs) with all third-party providers listed below, requiring them to process data only for the purposes for which they are engaged by Anytap. These providers have their own privacy and cookie policies, which we recommend reviewing independently."},{"t":"table","rows":[["Provider","Service Type","Privacy Policy"],["Google Analytics","Web analytics","policies.google.com/privacy"],["Amplitude","Product analytics","amplitude.com/privacy"],["Mixpanel","Event analytics","mixpanel.com/legal/privacy-policy"],["Cloudflare","Security / DDoS protection","cloudflare.com/privacypolicy"],["Google reCAPTCHA","Bot detection","policies.google.com/privacy"]]},{"t":"h2","x":"6. Managing Your Cookie Preferences"},{"t":"p","x":"You have several options for controlling or limiting how cookies are used when you interact with the Anytap Platform:"},{"t":"h3","x":"6.1 Anytap Cookie Preference Center"},{"t":"p","x":"When you first visit the Anytap Platform, you will be presented with a cookie consent banner. You may accept all cookies, reject non-essential cookies, or customize your preferences by category. You can revisit and update your preferences at any time by clicking the \"Cookie Settings\" link in the footer of our website."},{"t":"h3","x":"6.2 Browser-Level Controls"},{"t":"p","x":"Most web browsers allow you to control cookies through their settings. You can configure your browser to:"},{"t":"p","x":"Block all cookies;"},{"t":"p","x":"Block third-party cookies only;"},{"t":"p","x":"Clear existing cookies;"},{"t":"p","x":"Notify you when a cookie is being set."},{"t":"p","x":"Please note that disabling certain cookies — particularly Strictly Necessary cookies — may prevent you from accessing key features of the Anytap Platform, including account login and transaction processing."},{"t":"p","x":"Browser-specific guidance is available at the following links:"},{"t":"p","x":"Google Chrome: support.google.com/chrome/answer/95647"},{"t":"p","x":"Mozilla Firefox: support.mozilla.org/kb/cookies-information-websites-store-on-your-computer"},{"t":"p","x":"Apple Safari: support.apple.com/guide/safari/manage-cookies"},{"t":"p","x":"Microsoft Edge: support.microsoft.com/microsoft-edge/delete-cookies"},{"t":"h3","x":"6.3 Opt-Out from Analytics Providers"},{"t":"p","x":"You may opt out of analytics tracking directly with our third-party providers:"},{"t":"p","x":"Google Analytics: Install the Google Analytics Opt-out Browser Add-on at tools.google.com/dlpage/gaoptout"},{"t":"p","x":"Amplitude: Submit an opt-out request at amplitude.com/privacy"},{"t":"p","x":"Mixpanel: Opt out via mixpanel.com/optout"},{"t":"h2","x":"7. Cookie Retention Periods"},{"t":"p","x":"Cookies on the Anytap Platform are retained for varying durations depending on their purpose. Session cookies expire automatically when you close your browser. Persistent cookies remain on your device until they expire or you delete them. The specific durations applicable to each cookie are listed in Section 3 above."},{"t":"p","x":"We conduct a full cookie inventory review at least annually, or following any material change to the Platform, and retire cookies that are no longer necessary for the operation of the Services."},{"t":"h2","x":"8. Do Not Track Signals"},{"t":"p","x":"Some browsers include a \"Do Not Track\" (DNT) feature that signals to websites that you do not wish to have your online activity tracked. As there is currently no universally accepted technical standard for responding to DNT signals, the Anytap Platform does not alter its behavior in response to DNT signals at this time."},{"t":"p","x":"We are committed to honoring user privacy preferences and will update this Policy if and when the W3C or an equivalent standards body adopts a consensus DNT specification."},{"t":"h2","x":"9. Changes to This Cookie Policy"},{"t":"p","x":"We may update this Cookie Policy periodically to reflect changes in our use of cookies, applicable law, or operational practices. We will notify you of material changes by displaying a prominent notice on the Anytap Platform or by sending an email notification at least 14 days prior to the changes taking effect."},{"t":"p","x":"The most current version of this Cookie Policy is always available at anytap.io/cookies. Your continued use of the Platform following the effective date of any update constitutes your acceptance of the revised Policy."},{"t":"h2","x":"10. Contact Us"},{"t":"p","x":"If you have any questions or concerns about this Cookie Policy or our use of cookies, please contact us through the appropriate channel below:"},{"t":"table","rows":[["Channel","Contact","Notes"],["General Support","support@anytap.io","English only"],["Business / Partnership","biz@anytap.io","B2B and partnership inquiries"]]},{"t":"p","x":"© 2026 Anytap. All rights reserved."}]},"terms":{"title":"Terms of Service","effective":"Effective Date: June 1, 2026   |   Last Updated: June 1, 2026","blocks":[{"t":"h2","x":"1. Acceptance of Terms"},{"t":"p","x":"By accessing or using any Anytap service — including the Anytap Card, Anytap Pay, and any related mobile or web application (collectively, the \"Services\") — you (\"User,\" \"you,\" or \"your\") agree to be bound by these Terms of Service (\"Terms\"). If you do not agree to these Terms, you must immediately discontinue use of all Services."},{"t":"p","x":"The Services are operated under the Anytap brand (\"Anytap,\" \"we,\" \"us,\" or \"our\")."},{"t":"h2","x":"2. Eligibility"},{"t":"p","x":"To use the Services, you must:"},{"t":"p","x":"Be at least 18 years of age (or the age of majority in your jurisdiction);"},{"t":"p","x":"Not be a resident of, or located in, a country subject to U.S. Office of Foreign Assets Control (OFAC) sanctions or other applicable international sanctions;"},{"t":"p","x":"Successfully complete Anytap's identity verification (KYC) process;"},{"t":"p","x":"Not have been previously suspended or removed from any Anytap service."},{"t":"p","x":"Anytap reserves the right to decline or restrict access to the Services in jurisdictions where applicable laws or regulations prohibit or restrict the provision of cryptocurrency-related financial services."},{"t":"h2","x":"3. Identity Verification (KYC) and AML Compliance"},{"t":"h3","x":"3.1 KYC Requirements"},{"t":"p","x":"All users must complete identity verification before accessing card issuance or payment services. This process requires submission of:"},{"t":"p","x":"A valid government-issued photo identification document (passport, national ID, or driver's license);"},{"t":"p","x":"A live selfie for biometric verification;"},{"t":"p","x":"Proof of residential address (where required);"},{"t":"p","x":"Mobile phone number and email address."},{"t":"p","x":"KYC verification is administered by Anytap. Anytap is solely responsible for the collection, handling, and safeguarding of all identity verification data submitted by users."},{"t":"h3","x":"3.2 AML / CFT Policy"},{"t":"p","x":"Anytap operates in full compliance with applicable Anti-Money Laundering (AML) and Counter-Financing of Terrorism (CFT) regulations. We are required by law to monitor transactions for suspicious activity and to report to relevant authorities where required. Anytap reserves the right to suspend, restrict, or terminate any account that is flagged for suspicious activity, without prior notice where legally required."},{"t":"h3","x":"3.3 Data Retention"},{"t":"p","x":"Personal information collected during KYC verification is retained for a minimum of five (5) years following account closure, in accordance with applicable AML regulations and our Privacy Policy (anytap.io/privacy)."},{"t":"h2","x":"4. Anytap Card — Terms of Use"},{"t":"h3","x":"4.1 Nature of the Card"},{"t":"p","x":"The Anytap Card is a prepaid debit card, not a credit card. Anytap offers two card types:"},{"t":"table","rows":[["Card Type","Network","Key Features"],["Virtual Card","Visa","Issued instantly upon KYC approval. Supports online payments, Apple Pay, and Google Pay."],["Physical Card","Visa","Dispatched after KYC approval. Supports in-store payments, ATM withdrawals, and Google Pay. Apple Pay support coming Q3 2026."]]},{"t":"p","x":"Cards are issued through our card infrastructure partner, WasabiCard (Wasabi Group Ltd), which holds U.S. & Canada MSB, U.S. MTL, PCI DSS Level 1, Singapore Visa TPA, and Singapore Visa PIF licenses. Anytap does not extend credit and is not responsible for repayment obligations."},{"t":"h3","x":"4.2 Card Issuance"},{"t":"p","x":"Card issuance is subject to successful KYC approval."},{"t":"p","x":"A card issuance fee applies per card issued. The applicable fee is displayed at the time of application and may vary by card type. Anytap reserves the right to update issuance fees with prior notice."},{"t":"p","x":"Virtual cards are issued immediately upon KYC approval."},{"t":"p","x":"Physical cards are dispatched within approximately 3–4 weeks following order confirmation (including card production of 2–3 weeks and shipping of approximately 1 week), subject to destination country."},{"t":"h3","x":"4.3 Loading / Top-Up"},{"t":"p","x":"Cards may be loaded using USDT (TRC-20, BEP-20, ERC-20), USDC, and other supported cryptocurrencies."},{"t":"p","x":"A top-up fee applies to all cryptocurrency-to-card balance conversions. The applicable rate is displayed in your account dashboard at the time of top-up."},{"t":"p","x":"Users are solely responsible for compliance with applicable travel rule regulations in their jurisdiction. Direct transfers from domestic Korean exchanges (e.g., Upbit, Bithumb) are not supported due to travel rule restrictions; routing via internationally compliant exchanges is required."},{"t":"p","x":"Top-up transactions are processed in real time following blockchain confirmation. Anytap is not liable for delays caused by network congestion or third-party processing times."},{"t":"h3","x":"4.4 Transactions and Fees"},{"t":"p","x":"The Anytap Virtual Card can be used at any Visa-network merchant worldwide. The Anytap Physical Card can be used at any Visa-network merchant worldwide."},{"t":"p","x":"A foreign transaction fee of 0.7% per transaction applies when spending in currencies other than USD."},{"t":"p","x":"ATM cash withdrawals are subject to applicable ATM operator fees. ATM withdrawal limits apply per the card usage limits set out below."},{"t":"p","x":"No monthly maintenance fee is charged."},{"t":"p","x":"Anytap is not responsible for merchant refusals, network outages, or third-party processing errors."},{"t":"p","x":"The following transaction limits apply to the Anytap Card:"},{"t":"table","rows":[["Limit Type","Virtual Card (Visa)","Physical Card (Visa)"],["Per transaction","$200,000","$20,000"],["Daily spending limit","$200,000","$250,000"],["Monthly spending limit","$1,000,000","$1,000,000"],["ATM withdrawal — per transaction","N/A","$1,500"],["ATM withdrawal — daily limit","N/A","$1,500 (max 30 transactions)"],["ATM withdrawal — monthly limit","N/A","$15,000"],["Apple Pay / Google Pay — per transaction","$100,000","N/A (Google Pay: $20,000)"]]},{"t":"h3","x":"4.5 Card Controls"},{"t":"p","x":"Users may freeze, unfreeze, or request replacement of their card at any time via the Anytap application or dashboard. Anytap reserves the right to suspend card functionality where fraud, suspicious activity, or AML concerns are identified."},{"t":"h3","x":"4.6 Card Expiry and Remaining Balance"},{"t":"p","x":"Cards are subject to expiry as indicated on the card. Users are responsible for spending or transferring any remaining balance prior to card expiry. Anytap is not liable for balances lost due to card expiry or account inactivity."},{"t":"h2","x":"5. Anytap Pay — Business Payment Services"},{"t":"h3","x":"5.1 Service Description"},{"t":"p","x":"Anytap Pay is an enterprise cryptocurrency payment infrastructure service, accessible via REST API. It supports cryptocurrency payment acceptance, invoicing, subscription billing, mass payouts, and fiat off-ramp functions."},{"t":"h3","x":"5.2 Permitted Use"},{"t":"p","x":"Anytap Pay may be used by legally registered businesses for lawful commercial purposes only. Use of Anytap Pay for any prohibited activity (see Section 7) will result in immediate service termination and may be reported to relevant authorities."},{"t":"h3","x":"5.3 Settlement"},{"t":"p","x":"Cryptocurrency received via Anytap Pay may be held in custody, auto-converted, or withdrawn to designated wallets in accordance with the user's account settings and applicable processing times. Settlement timelines are subject to blockchain confirmation speeds and Anytap's internal processing schedules."},{"t":"h2","x":"6. Cryptocurrency Risk Disclosure"},{"t":"p","x":"IMPORTANT — PLEASE READ CAREFULLY."},{"t":"p","x":"Cryptocurrency values are highly volatile. The value of USDT, USDC, and other cryptocurrencies may fluctuate significantly. Anytap does not guarantee the value of any cryptocurrency held in your account."},{"t":"p","x":"The Anytap Card is not FDIC insured or covered by any equivalent government-backed deposit protection scheme, including the U.S. FDIC, U.S. SIPC, or Singapore SDIC."},{"t":"p","x":"Cryptocurrency transactions are generally irreversible. Once a transfer is confirmed on the blockchain, it cannot be reversed or cancelled."},{"t":"p","x":"Regulatory risk. The legal and regulatory status of cryptocurrency varies by jurisdiction and may change. Users are responsible for ensuring compliance with all applicable laws in their country of residence."},{"t":"p","x":"Tax obligations. Users are solely responsible for determining and fulfilling any tax obligations arising from the use of the Services, including but not limited to capital gains tax and any obligations arising from cryptocurrency-to-fiat conversions. Anytap recommends consulting a qualified tax advisor."},{"t":"p","x":"For a full description of applicable risks, please refer to our Risk Disclosure Statement at anytap.io/disclosure."},{"t":"h2","x":"7. Prohibited Activities"},{"t":"p","x":"You agree not to use the Services, directly or indirectly, for:"},{"t":"p","x":"Any illegal activity, including but not limited to money laundering, terrorist financing, fraud, or tax evasion;"},{"t":"p","x":"Purchasing, selling, or facilitating the trade of illegal goods or services (including narcotics, weapons, or child sexual abuse material);"},{"t":"p","x":"Circumventing international sanctions or OFAC-designated entity restrictions;"},{"t":"p","x":"Operating unlicensed gambling, Ponzi, or pyramid scheme platforms;"},{"t":"p","x":"Any activity that violates the rules of the Visa payment networks;"},{"t":"p","x":"Transactions involving any merchant or platform on Anytap's high-risk blacklist, as updated from time to time;"},{"t":"p","x":"Attempting to access, alter, or disrupt Anytap's systems, networks, or data;"},{"t":"p","x":"Providing false or misleading information during KYC or any account operation."},{"t":"p","x":"Violation of these prohibitions will result in immediate account termination and may result in reporting to relevant law enforcement or regulatory authorities."},{"t":"h2","x":"8. Account Suspension and Termination"},{"t":"p","x":"Anytap reserves the right to suspend or terminate any account, with or without prior notice, in the following circumstances:"},{"t":"p","x":"Suspected violation of these Terms or applicable law;"},{"t":"p","x":"Receipt of a legal order, regulatory directive, or law enforcement request;"},{"t":"p","x":"Identification of suspicious, fraudulent, or high-risk transaction patterns;"},{"t":"p","x":"Failure to maintain satisfactory KYC status."},{"t":"p","x":"Where legally permissible, Anytap will provide prior notice of suspension and an opportunity to appeal. In cases of suspected fraud or regulatory obligation, suspension may be immediate and without prior notice."},{"t":"p","x":"Upon termination, any remaining card balance will be made available for withdrawal subject to AML clearance and applicable hold periods."},{"t":"h2","x":"9. Referral Program"},{"t":"p","x":"Anytap operates a referral program under which eligible participants may earn commissions. Participation is subject to the following conditions:"},{"t":"p","x":"Referral participants are classified as Silver or Premium tier. Commission rates differ by tier. Silver participants earn up to 0.2% of referred users' top-up amounts; Premium participants earn up to 0.4%."},{"t":"p","x":"A fixed referral bonus of $20 USDT is paid per referred user who completes KYC verification and receives a card."},{"t":"p","x":"Commissions are calculated on a monthly basis and paid in USDT between the 1st and 7th day of the following month."},{"t":"p","x":"The minimum payout threshold is $1 USDT. No partial month payments are made."},{"t":"p","x":"Anytap reserves the right to modify, suspend, or discontinue the referral program at any time with reasonable prior notice."},{"t":"p","x":"Participants are solely responsible for complying with applicable laws regarding the promotion of financial services and the receipt of referral income in their jurisdiction."},{"t":"h2","x":"10. Limitation of Liability"},{"t":"p","x":"TO THE MAXIMUM EXTENT PERMITTED BY APPLICABLE LAW:"},{"t":"p","x":"Anytap shall not be liable for any indirect, incidental, consequential, or punitive damages, including but not limited to loss of profits, loss of data, or loss of business opportunity, arising from or related to the use of the Services."},{"t":"p","x":"Anytap's total aggregate liability for any claim arising under or in connection with these Terms shall not exceed the total fees paid by the User to Anytap in the twelve (12) months preceding the event giving rise to the claim."},{"t":"p","x":"Anytap is not responsible for losses arising from cryptocurrency market volatility, blockchain network failures, exchange rate fluctuations, or actions of third-party service providers, including our card infrastructure partner or cryptocurrency wallet custody provider."},{"t":"p","x":"Anytap is not responsible for any failure, delay, or error resulting from circumstances beyond our reasonable control, including but not limited to network outages, regulatory actions, or acts of God."},{"t":"p","x":"Nothing in these Terms limits Anytap's liability for gross negligence, willful misconduct, or any liability that cannot be excluded under applicable law."},{"t":"h2","x":"11. Intellectual Property"},{"t":"p","x":"All content, trademarks, service marks, logos, and technology associated with the Anytap Services are the exclusive property of their respective owners. You may not copy, reproduce, distribute, or create derivative works from any Anytap content without prior written consent."},{"t":"h2","x":"12. Privacy Policy"},{"t":"p","x":"Your use of the Services is also governed by Anytap's Privacy Policy, which is incorporated by reference into these Terms. Please review the Privacy Policy at anytap.io/privacy."},{"t":"h2","x":"13. Modifications to Terms"},{"t":"p","x":"Anytap reserves the right to modify these Terms at any time. We will provide notice of material changes via email or prominent in-app notification at least 14 days prior to the effective date of any change. Continued use of the Services following the effective date of any modification constitutes acceptance of the revised Terms."},{"t":"h2","x":"14. Governing Law and Dispute Resolution"},{"t":"p","x":"These Terms shall be governed by and construed in accordance with the laws of the State of Delaware, United States, without regard to its conflict of law provisions."},{"t":"p","x":"Any dispute arising out of or in connection with these Terms shall first be subject to good-faith negotiation. If unresolved within 30 days, disputes shall be submitted to binding arbitration under the rules of the American Arbitration Association (AAA), conducted in English in the State of Delaware."},{"t":"p","x":"Nothing in this clause prevents either party from seeking urgent injunctive or equitable relief from a court of competent jurisdiction."},{"t":"h2","x":"15. Contact Information"},{"t":"p","x":"For questions regarding these Terms, please contact us through the appropriate channel below:"},{"t":"table","rows":[["Channel","Contact","Notes"],["General Support","support@anytap.io","English only"],["Business / Partnership","biz@anytap.io","B2B and partnership inquiries"]]},{"t":"p","x":"© 2026 Anytap. All rights reserved."}]},"disclosure":{"title":"Risk Disclosure Statement","effective":"Effective Date: June 1, 2026   |   Last Updated: June 1, 2026","blocks":[{"t":"table","rows":[["IMPORTANT NOTICE — PLEASE READ CAREFULLY BEFORE USING ANYTAP SERVICES This Risk Disclosure Statement describes material risks associated with the use of Anytap's cryptocurrency debit card and payment services. These risks may result in the partial or total loss of funds. You should not use Anytap services unless you fully understand and accept these risks. This document does not constitute financial, investment, legal, or tax advice. Anytap strongly recommends that you consult a qualified independent professional advisor before making any financial decisions."]]},{"t":"h2","x":"1. About This Disclosure"},{"t":"p","x":"Anytap (\"we,\" \"us,\" or \"our\") provides a cryptocurrency-linked prepaid debit card and business payment infrastructure (collectively, the \"Services\"). The Services allow users to load supported cryptocurrencies — including USDT and USDC — and use them for everyday spending via the Visa network (physical card) and Visa network (virtual card)."},{"t":"p","x":"Cryptocurrency-linked financial services carry unique and significant risks that differ materially from those associated with traditional bank accounts, credit cards, or regulated investment products. This Risk Disclosure Statement is provided to ensure that all users have a clear understanding of these risks prior to using the Services."},{"t":"p","x":"By accessing or using the Services, you confirm that you have read, understood, and accepted the risks described in this Statement."},{"t":"h2","x":"2. Cryptocurrency Volatility Risk"},{"t":"p","x":"The value of cryptocurrencies, including stablecoins such as USDT and USDC, is subject to significant price volatility. Unlike traditional fiat currencies, cryptocurrencies:"},{"t":"p","x":"Are not issued or backed by any central bank, government, or sovereign authority;"},{"t":"p","x":"May experience rapid and unpredictable fluctuations in value within short time periods;"},{"t":"p","x":"Are subject to speculative trading, market sentiment, and macroeconomic factors beyond Anytap's control;"},{"t":"p","x":"May lose value substantially or entirely due to technical failures, market manipulation, or regulatory intervention."},{"t":"p","x":"While USDT and USDC are designed to maintain a 1:1 peg with the U.S. dollar, this peg is not guaranteed and may break under certain market conditions. Anytap makes no representation that the value of any cryptocurrency held in your account will remain stable or retain any particular value at any time."},{"t":"p","x":"Users are solely responsible for evaluating cryptocurrency price risks and for ensuring that their use of the Services is consistent with their personal financial situation."},{"t":"h2","x":"3. Stablecoin-Specific Risks"},{"t":"p","x":"Even though Anytap primarily supports stablecoins (USDT and USDC), these instruments carry specific risks that users must understand:"},{"t":"table","rows":[["Risk Type","Description"],["De-pegging risk","A stablecoin may lose its 1:1 peg to USD due to insufficient collateral, liquidity crises, or issuer insolvency."],["Issuer / counterparty risk","USDT is issued by Tether Ltd. and USDC by Circle Internet Financial. The financial soundness and regulatory compliance of these issuers may change."],["Smart contract risk","Stablecoins operate on blockchain smart contracts that may contain vulnerabilities exploitable by malicious actors."],["Regulatory risk","Regulators may restrict, prohibit, or impose conditions on the use of stablecoins in certain jurisdictions with little or no notice."],["Reserve transparency","The actual reserve composition and audit quality of stablecoin issuers may not fully reflect publicly stated backing."]]},{"t":"h2","x":"4. Regulatory and Legal Risk"},{"t":"p","x":"The legal and regulatory status of cryptocurrency assets varies significantly across jurisdictions and is subject to rapid change. Users must be aware of the following:"},{"t":"p","x":"Cryptocurrency activities may be restricted, prohibited, or subject to licensing requirements in your country or region of residence;"},{"t":"p","x":"Regulators in multiple jurisdictions, including the United States, European Union, and various Asian jurisdictions, are actively developing and revising cryptocurrency regulatory frameworks;"},{"t":"p","x":"Changes in law or regulation may render certain Anytap services unavailable to users in affected jurisdictions with limited or no advance notice;"},{"t":"p","x":"Anytap reserves the right to restrict, suspend, or terminate access to the Services in any jurisdiction in order to comply with applicable legal or regulatory obligations;"},{"t":"p","x":"Users are solely responsible for determining whether their use of the Services is lawful in their jurisdiction and for complying with all applicable laws, including reporting and licensing requirements."},{"t":"p","x":"Anytap does not provide legal advice. If you are uncertain about the legality of using cryptocurrency services in your jurisdiction, you should seek independent legal counsel."},{"t":"h2","x":"5. No Deposit Insurance or Government Protection"},{"t":"p","x":"IMPORTANT: Funds held in your Anytap Card balance or Anytap Pay account are NOT protected by any government-backed deposit insurance scheme, including:"},{"t":"p","x":"The U.S. Federal Deposit Insurance Corporation (FDIC);"},{"t":"p","x":"The U.S. Securities Investor Protection Corporation (SIPC);"},{"t":"p","x":"The Singapore Deposit Insurance Corporation (SDIC);"},{"t":"p","x":"Any equivalent national or regional deposit protection scheme."},{"t":"p","x":"In the event of Anytap's insolvency, the insolvency of a financial infrastructure partner, or a security breach resulting in loss of funds, you may not recover all or any part of your balance. You should not hold funds in your Anytap account that you cannot afford to lose."},{"t":"h2","x":"6. Transaction Irreversibility Risk"},{"t":"p","x":"Blockchain transactions are, by their nature, irreversible once confirmed on the network. This means:"},{"t":"p","x":"Cryptocurrency sent to an incorrect wallet address cannot be recovered by Anytap;"},{"t":"p","x":"Transactions broadcast to the blockchain cannot be reversed, cancelled, or charged back by Anytap;"},{"t":"p","x":"In the event of unauthorized access to your account resulting in fraudulent transfers, Anytap cannot guarantee recovery of transferred funds;"},{"t":"p","x":"Users are solely responsible for verifying all wallet addresses and transaction details before initiating any transfer."},{"t":"p","x":"Anytap implements security measures to protect your account; however, these measures do not eliminate the risk of unauthorized access. You are responsible for maintaining the security of your login credentials, two-factor authentication device, and any recovery codes."},{"t":"h2","x":"7. Technology and Cybersecurity Risk"},{"t":"p","x":"Anytap's Services rely on complex technology infrastructure, including blockchain networks, cloud computing services, third-party APIs, and payment processing systems. The following technology-related risks may affect the Services:"},{"t":"h3","x":"7.1 System Outages and Service Interruptions"},{"t":"p","x":"The Anytap Platform may experience downtime, outages, or reduced functionality due to maintenance, software defects, hardware failures, or circumstances beyond our control. During such periods, you may be temporarily unable to access your funds, make payments, or perform account management actions."},{"t":"h3","x":"7.2 Blockchain Network Risk"},{"t":"p","x":"Transactions processed through Anytap depend on the underlying blockchain network (e.g., Ethereum, TRON, BNB Smart Chain, or other supported networks). Blockchain networks may experience:"},{"t":"p","x":"Network congestion resulting in delayed transaction confirmation;"},{"t":"p","x":"Hard forks, protocol upgrades, or chain splits that affect token compatibility;"},{"t":"p","x":"51% attacks or other consensus layer vulnerabilities;"},{"t":"p","x":"Permanent or temporary network failures."},{"t":"h3","x":"7.3 Cybersecurity Threats"},{"t":"p","x":"Despite implementing industry-standard security measures, Anytap and its infrastructure partners remain potential targets for cyberattacks, including hacking, phishing, social engineering, malware, and ransomware. A successful cyberattack could result in unauthorized access to user accounts or loss of funds. Anytap is not liable for losses arising from cybersecurity incidents beyond its reasonable control."},{"t":"h3","x":"7.4 Third-Party Infrastructure Risk"},{"t":"p","x":"Anytap relies on third-party service providers for card issuance (via WasabiCard), cryptocurrency wallet custody, payment processing, KYC verification, and cloud infrastructure. The failure, insolvency, or regulatory action against any such provider may disrupt the availability of the Services. Anytap operates under a white-label card issuance arrangement and is subject to the operational continuity of its card infrastructure partner."},{"t":"h2","x":"8. Exchange Rate and Conversion Risk"},{"t":"p","x":"When you use the Anytap Card to make a purchase or withdrawal in a currency other than USD, your card balance (denominated in stablecoin equivalent) will be converted to the local currency at the prevailing exchange rate at the time of the transaction. The following risks apply:"},{"t":"p","x":"Exchange rates fluctuate continuously and the rate applied to your transaction may differ from rates published on financial websites or quoted by currency exchange services;"},{"t":"p","x":"A foreign transaction fee of 0.7% per transaction applies in addition to the standard top-up fee when spending in currencies other than USD;"},{"t":"p","x":"Exchange rate movements between the time you load your card and the time you spend may result in you receiving less value than anticipated;"},{"t":"p","x":"Anytap does not offer hedging, forward contracts, or any other mechanism to lock in exchange rates."},{"t":"h2","x":"9. AML / KYC Compliance Risk"},{"t":"p","x":"Anytap is required to comply with applicable Anti-Money Laundering (AML) and Know Your Customer (KYC) regulations. As a result:"},{"t":"p","x":"Your account may be suspended or terminated if you fail to provide satisfactory identity verification documentation;"},{"t":"p","x":"Transactions that trigger AML monitoring thresholds may be delayed, blocked, or reported to relevant financial intelligence authorities without prior notice to you;"},{"t":"p","x":"Anytap may be required to freeze account balances pending regulatory investigation, in which case you may temporarily or permanently be unable to access your funds;"},{"t":"p","x":"In jurisdictions where Anytap determines that continued operation poses unacceptable regulatory risk, services may be withdrawn with limited notice."},{"t":"h2","x":"10. Tax Risk"},{"t":"p","x":"The use of cryptocurrency — including loading funds onto the Anytap Card, making purchases, and receiving referral commissions — may constitute a taxable event in your jurisdiction. Tax treatment of cryptocurrency transactions varies significantly across countries and may include:"},{"t":"p","x":"Capital gains tax on the disposal of cryptocurrency;"},{"t":"p","x":"Income tax on referral commissions received in USDT;"},{"t":"p","x":"VAT or goods and services tax on certain transactions;"},{"t":"p","x":"Reporting obligations to local tax authorities."},{"t":"p","x":"Anytap does not provide tax advice and does not report your transactions to tax authorities on your behalf (except where legally required to do so). You are solely responsible for determining your tax obligations and for complying with all applicable tax laws. Anytap strongly recommends consulting a qualified tax advisor."},{"t":"h2","x":"11. Referral Program Risk"},{"t":"p","x":"Participants in the Anytap Referral Program should be aware of the following risks:"},{"t":"p","x":"Commission rates and program terms are subject to change at Anytap's discretion with reasonable prior notice;"},{"t":"p","x":"Commission payments are made in USDT, which carries the volatility and issuer risks described in Sections 2 and 3;"},{"t":"p","x":"Referral commissions are settled monthly: earnings accrued during a given calendar month are paid between the 1st and 7th day of the following month;"},{"t":"p","x":"Anytap does not guarantee any minimum level of referral income;"},{"t":"p","x":"The referral program may be modified, suspended, or discontinued at any time;"},{"t":"p","x":"Participants are responsible for complying with applicable laws in their jurisdiction regarding the promotion of financial services and the receipt of referral income."},{"t":"h2","x":"12. Limitation of Anytap's Liability"},{"t":"p","x":"To the maximum extent permitted by applicable law, Anytap shall not be liable for any losses, damages, or costs arising from or related to:"},{"t":"p","x":"Fluctuations in the value of cryptocurrency or stablecoins;"},{"t":"p","x":"The insolvency, failure, or regulatory action against any card issuer, payment network, or financial infrastructure partner;"},{"t":"p","x":"Unauthorized access to your account resulting from your failure to maintain account security;"},{"t":"p","x":"Blockchain network failures, delays, or errors;"},{"t":"p","x":"Service interruptions or downtime;"},{"t":"p","x":"Changes in applicable law or regulation;"},{"t":"p","x":"Your failure to comply with applicable tax, AML, or other legal obligations."},{"t":"p","x":"Nothing in this Risk Disclosure Statement or Anytap's Terms of Service limits liability for gross negligence, willful misconduct, or any liability that cannot be excluded under applicable law."},{"t":"h2","x":"13. No Investment Advice"},{"t":"p","x":"Nothing on the Anytap Platform, including this Risk Disclosure Statement, constitutes financial advice, investment advice, trading advice, or any other type of professional advice. Anytap is a payment services platform and not a licensed investment advisor, broker-dealer, or financial planner."},{"t":"p","x":"Any information provided by Anytap regarding cryptocurrency markets, stablecoin issuers, or fintech industry developments is for general informational purposes only and should not be relied upon as the basis for any financial decision. Past performance of any asset is not indicative of future results."},{"t":"h2","x":"14. Updates to This Disclosure"},{"t":"p","x":"Anytap may update this Risk Disclosure Statement from time to time to reflect changes in our Services, applicable law, or the risk environment. We will notify users of material changes via email or prominent notice on the Platform at least 14 days prior to the effective date."},{"t":"p","x":"The most current version of this Statement is always available at anytap.io/disclosure. Your continued use of the Services after the effective date of any update constitutes your acceptance of the revised Statement."},{"t":"h2","x":"15. Contact Us"},{"t":"p","x":"If you have any questions regarding this Risk Disclosure Statement, please contact us through the appropriate channel below:"},{"t":"table","rows":[["Channel","Contact","Notes"],["General Support","support@anytap.io","English only"],["Business / Partnership","biz@anytap.io","B2B and partnership inquiries"]]},{"t":"p","x":"© 2026 Anytap. All rights reserved."}]}};
